import{c as t,Q as s,j as a,m as i}from"./chunks/framework.DGHXLY8X.js";const u=JSON.parse('{"title":"Consuming streaming outputs","description":"","frontmatter":{},"headers":[],"relativePath":"operating/streaming-outputs.md","filePath":"operating/streaming-outputs.md","lastUpdated":1780984191000}'),o={name:"operating/streaming-outputs.md"};function n(d,e,r,c,h,l){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="consuming-streaming-outputs" tabindex="-1">Consuming streaming outputs <a class="header-anchor" href="#consuming-streaming-outputs" aria-label="Permalink to &quot;Consuming streaming outputs&quot;">​</a></h1><p>VideoNode exposes each stream over three protocols simultaneously. The stream ID you set in the REST API is the identifier end-to-end: it appears in the RTSP path, the SRT <code>streamid</code> parameter, the WebRTC query string, and the Prometheus metrics label.</p><p>The default ports are <code>:8554</code> for RTSP, <code>:6001</code> for SRT, and <code>:8090</code> for the HTTP/WebRTC API. Override them in <code>config.toml</code> or via environment variables (<code>VIDEONODE_STREAMING_RTSP_PORT</code>, <code>VIDEONODE_SRT_ADDR</code>, <code>VIDEONODE_SERVER_PORT</code>).</p><p>The encoder only starts when the first reader connects. Expect up to a few seconds of buffering on the initial connection. When the last reader disconnects, the encoder is not torn down immediately: a 30-second debounce keeps it warm so a reader that reconnects (for example, a WebRTC ICE flap that recovers) reattaches to the running encoder instead of waiting for a cold start.</p><h2 id="rtsp" tabindex="-1">RTSP <a class="header-anchor" href="#rtsp" aria-label="Permalink to &quot;RTSP&quot;">​</a></h2><p>To watch the stream with ffplay, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffplay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rtsp://localhost:8554/cam-lobby</span></span></code></pre></div><p>Replace <code>cam-lobby</code> with your stream ID. Any RTSP 1.0 client works: VLC, GStreamer, OBS.</p><h2 id="srt" tabindex="-1">SRT <a class="header-anchor" href="#srt" aria-label="Permalink to &quot;SRT&quot;">​</a></h2><p>To watch the stream with ffplay over SRT, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffplay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;srt://localhost:6001?streamid=cam-lobby&quot;</span></span></code></pre></div><p>The <code>streamid</code> query parameter is how the server routes the connection to the right encoder. VLC 4.x and mpv (with <code>--demuxer-lavf-o=streamid=cam-lobby</code>) also accept SRT URIs.</p><p>Two settings tune the SRT server, both via <code>config.toml</code> or an environment override. Environment overrides require the <code>VIDEONODE_</code> prefix on the key:</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Env override</th><th>Effect</th></tr></thead><tbody><tr><td><code>srt.enabled</code></td><td><code>true</code></td><td><code>VIDEONODE_SRT_ENABLED</code></td><td>Set <code>false</code> to disable the SRT server entirely.</td></tr><tr><td><code>srt.latency</code></td><td><code>20</code></td><td><code>VIDEONODE_SRT_LATENCY</code></td><td>Receiver latency in milliseconds.</td></tr></tbody></table><h2 id="webrtc" tabindex="-1">WebRTC <a class="header-anchor" href="#webrtc" aria-label="Permalink to &quot;WebRTC&quot;">​</a></h2><p>The simplest way to watch a stream over WebRTC is the built-in UI: log in to <code>http://&lt;host&gt;:8090/streams</code> and click the stream. The browser opens a peer connection for you.</p><h3 id="embed-a-single-stream" tabindex="-1">Embed a single stream <a class="header-anchor" href="#embed-a-single-stream" aria-label="Permalink to &quot;Embed a single stream&quot;">​</a></h3><p>Each stream also has a chromeless URL designed to drop into an iframe or open in a kiosk:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;host&gt;:8090/video?stream=&lt;stream_id&gt;</span></span></code></pre></div><p>Optional query parameters:</p><table tabindex="0"><thead><tr><th>Param</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>muted</code></td><td><code>true</code></td><td>Set to <code>false</code> to start with audio.</td></tr><tr><td><code>stats</code></td><td><code>false</code></td><td>Show the debug overlay on load. Toggles on double-click.</td></tr></tbody></table><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://videonode.local:8090/video?stream=cam-lobby&amp;muted=false&amp;stats=true</span></span></code></pre></div><p>The view renders only the player at full viewport on a black background. No nav, no chrome.</p><h3 id="debug-stats" tabindex="-1">Debug stats <a class="header-anchor" href="#debug-stats" aria-label="Permalink to &quot;Debug stats&quot;">​</a></h3><p>The built-in stats overlay calls <code>RTCPeerConnection.getStats()</code> once per second and shows resolution, FPS, frames decoded and dropped, codecs, current bitrate, jitter buffer delay, A/V sync offset, packet loss, and RTT. Open any stream in the UI to see it, or pass <code>?stats=true</code> on the embed URL, or double-click the player to toggle it. This is purely browser-side instrumentation; no extra endpoint is involved.</p><p>For server-side metrics across all consumers, scrape Prometheus at <code>/api/metrics</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/api/metrics</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[.[] | select(.name | startswith(&quot;videonode_webrtc&quot;))]&#39;</span></span></code></pre></div><p>Relevant series:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Labels</th><th>What</th></tr></thead><tbody><tr><td><code>videonode_webrtc_active_peers</code></td><td><code>stream_id</code></td><td>Connected peers per stream.</td></tr><tr><td><code>videonode_webrtc_peer_nacks_total</code></td><td><code>stream_id</code>, <code>peer_id</code></td><td>NACK count (packet loss indicator).</td></tr><tr><td><code>videonode_webrtc_peer_plis_total</code></td><td><code>stream_id</code>, <code>peer_id</code></td><td>PLI count (decoder requested a keyframe).</td></tr><tr><td><code>videonode_webrtc_peer_jitter</code></td><td><code>stream_id</code>, <code>peer_id</code></td><td>Interarrival jitter in RTP units. Divide by 90000 for seconds.</td></tr><tr><td><code>videonode_webrtc_stream_bytes_total</code></td><td><code>stream_id</code></td><td>Bytes sent per stream.</td></tr></tbody></table><p>See <a href="./observability">observability</a> for the full metric inventory.</p><h3 id="custom-player" tabindex="-1">Custom player <a class="header-anchor" href="#custom-player" aria-label="Permalink to &quot;Custom player&quot;">​</a></h3><p>For a self-driven player, drive signaling against the daemon&#39;s WHEP (WebRTC-HTTP Egress Protocol) endpoint:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST http://&lt;host&gt;:8090/whep/&lt;stream_id&gt;</span></span>
<span class="line"><span>Content-Type: application/sdp</span></span>
<span class="line"><span>Body: your SDP offer</span></span></code></pre></div><p>The <code>201 Created</code> response carries your SDP answer in the body (<code>Content-Type: application/sdp</code>) and a <code>Location</code> header pointing at the session resource (<code>/whep/&lt;stream_id&gt;/&lt;session_id&gt;</code>). Set the answer as the remote description on your <code>RTCPeerConnection</code>. To tear the session down, send <code>DELETE</code> to that <code>Location</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE http://&lt;host&gt;:8090/whep/&lt;stream_id&gt;/&lt;session_id&gt;</span></span></code></pre></div><p>Authentication follows the daemon&#39;s <code>auth.type</code> setting, using the same Linux-account or basic credentials as the rest of the API. See <a href="./../reference/config-toml#auth">config.toml reference</a>.</p><h2 id="managing-live-streams-and-consumers" tabindex="-1">Managing live streams and consumers <a class="header-anchor" href="#managing-live-streams-and-consumers" aria-label="Permalink to &quot;Managing live streams and consumers&quot;">​</a></h2><p>To list the stream IDs that currently have an active producer, query <code>/api/streams/live</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/api/streams/live</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.streams&#39;</span></span></code></pre></div><p>To force-disconnect one consumer, send <code>DELETE</code> to <code>/api/streams/{stream_id}/{protocol}/consumers/{client_id}</code>, where <code>protocol</code> is <code>webrtc</code> or <code>srt</code> and <code>client_id</code> is the peer name or SRT consumer ID:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8090/api/streams/cam-lobby/webrtc/consumers/192.0.2.10</span></span></code></pre></div><h2 id="changing-capture-format-while-streaming" tabindex="-1">Changing capture format while streaming <a class="header-anchor" href="#changing-capture-format-while-streaming" aria-label="Permalink to &quot;Changing capture format while streaming&quot;">​</a></h2><p>To switch a source&#39;s resolution, FPS, or pixel format without dropping its connected consumers, post to <code>/api/devices/{device_id}/format</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8090/api/devices/hdmi0/format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;fourcc&quot;: &quot;NV12&quot;, &quot;width&quot;: 1920, &quot;height&quot;: 1080, &quot;fps&quot;: 30}&#39;</span></span></code></pre></div><p>The source re-opens the V4L2 device with the new format while keeping every attached consumer connected. This requires the native control plane to be enabled and the source already running; the call returns <code>503</code> otherwise.</p>`,46)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
